package com.loyu3c.rental;

import org.json.*;
import java.time.YearMonth;
import java.util.*;

/** Read-only report projection; monthly billing and dated cashflow are separate. */
final class OwnerReport {
    private static JSONArray rows(JSONObject b,String key){JSONArray a=b.optJSONArray(key);return a==null?new JSONArray():a;}
    private static Map<String,JSONObject> index(JSONArray a)throws JSONException{Map<String,JSONObject> m=new LinkedHashMap<>();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);m.put(r.getString("id"),r);}return m;}
    private static JSONObject empty(String id,String name)throws JSONException{return new JSONObject().put("id",id).put("name",name).put("billed",0L).put("paid",0L).put("remaining",0L).put("cash",0L).put("topups",0L).put("expenses",0L).put("held",0L).put("invoiceCount",0);}
    private static void add(JSONObject row,String key,long n)throws JSONException{row.put(key,Math.addExact(row.getLong(key),n));}
    static JSONObject build(JSONObject b,YearMonth month)throws JSONException {
        Map<String,JSONObject> units=index(rows(b,"units")),leases=index(rows(b,"leases")),properties=index(rows(b,"properties"));Map<String,JSONObject> perProperty=new LinkedHashMap<>(),perLease=new LinkedHashMap<>();
        for(JSONObject p:properties.values())perProperty.put(p.getString("id"),empty(p.getString("id"),p.getString("name")));
        String cutoff=month.atEndOfMonth().toString();JSONArray before=new JSONArray();for(int i=0;i<rows(b,"receipts").length();i++){JSONObject r=rows(b,"receipts").getJSONObject(i);if(r.getString("date").compareTo(cutoff)<=0)before.put(r);}
        for(JSONObject l:leases.values()){JSONObject u=units.get(l.getString("unitId"));if(u==null||!perProperty.containsKey(u.getString("propertyId")))throw new IllegalArgumentException("報表租約不動產關聯錯誤");JSONObject row=empty(l.getString("id"),l.getString("tenant")).put("propertyId",u.getString("propertyId")).put("code",l.getString("unitCodeSnapshot"));perLease.put(l.getString("id"),row);}
        for(int i=0;i<rows(b,"invoices").length();i++){JSONObject bill=rows(b,"invoices").getJSONObject(i);if(!month.toString().equals(bill.getString("month")))continue;JSONObject row=perLease.get(bill.getString("leaseId"));long total=Ledger.total(bill),paid=Ledger.paid(bill.getString("id"),before);add(row,"billed",total);add(row,"paid",paid);add(row,"remaining",total-paid);row.put("invoiceCount",row.getInt("invoiceCount")+1);}
        for(int i=0;i<rows(b,"receipts").length();i++){JSONObject r=rows(b,"receipts").getJSONObject(i);if(r.optBoolean("cash",true)&&r.getString("date").startsWith(month.toString()))add(perLease.get(r.getString("leaseId")),"cash",r.getLong("amount"));}
        for(int i=0;i<rows(b,"settlements").length();i++){JSONObject s=rows(b,"settlements").getJSONObject(i);JSONArray payments=s.getJSONArray("payments");for(int j=0;j<payments.length();j++){JSONObject p=payments.getJSONObject(j);if(p.getString("date").startsWith(month.toString()))add(perLease.get(s.getString("leaseId")),"topups",p.getLong("amount"));}}
        for(int i=0;i<rows(b,"deposits").length();i++){JSONObject d=rows(b,"deposits").getJSONObject(i);if(d.optBoolean("void")||d.getString("date").compareTo(cutoff)>0)continue;add(perLease.get(d.getString("leaseId")),"held",d.getString("kind").equals("收到押金")?d.getLong("amount"):-d.getLong("amount"));}
        JSONArray tenantRows=new JSONArray();for(JSONObject row:perLease.values()){for(String key:new String[]{"billed","paid","remaining","cash","topups","held"})add(perProperty.get(row.getString("propertyId")),key,row.getLong(key));JSONObject p=perProperty.get(row.getString("propertyId"));p.put("invoiceCount",p.getInt("invoiceCount")+row.getInt("invoiceCount"));row.put("status",row.getInt("invoiceCount")==0?"本月未建帳單":row.getLong("remaining")==0?"本月帳單已清":"本月帳單未付");JSONObject lease=leases.get(row.getString("id"));boolean overlaps=lease.getString("start").compareTo(cutoff)<=0&&lease.optString("terminatedOn",lease.getString("end")).compareTo(month.atDay(1).toString())>=0;if(overlaps||row.getInt("invoiceCount")>0||row.getLong("cash")>0||row.getLong("topups")>0||row.getLong("held")!=0)tenantRows.put(row);}
        for(int i=0;i<rows(b,"expenses").length();i++){JSONObject e=rows(b,"expenses").getJSONObject(i);if(e.optBoolean("void")||!e.getString("date").startsWith(month.toString()))continue;JSONArray splits=e.getJSONArray("splits");for(int j=0;j<splits.length();j++){JSONObject s=splits.getJSONObject(j);add(perProperty.get(s.getString("propertyId")),"expenses",s.getLong("amount"));}}
        JSONObject total=empty("total","全部不動產");JSONArray propertyRows=new JSONArray();for(JSONObject p:perProperty.values()){for(String key:new String[]{"billed","paid","remaining","cash","topups","expenses","held"})add(total,key,p.getLong(key));total.put("invoiceCount",total.getInt("invoiceCount")+p.getInt("invoiceCount"));p.put("net",p.getLong("cash")+p.getLong("topups")-p.getLong("expenses"));propertyRows.put(p);}total.put("net",total.getLong("cash")+total.getLong("topups")-total.getLong("expenses"));
        return new JSONObject().put("month",month.toString()).put("total",total).put("properties",propertyRows).put("tenants",tenantRows);
    }
    private static String cell(String s){if(s.matches("(?s)^\\s*[=+@-].*")&&!s.matches("-?\\d+"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
    private static void line(StringBuilder out,String... cells){for(int i=0;i<cells.length;i++){if(i>0)out.append(',');out.append(cell(cells[i]));}out.append("\r\n");}
    static String csv(JSONObject report)throws JSONException{
        StringBuilder out=new StringBuilder("\uFEFF");line(out,"月份","列別","不動產","房號","租客","當月已建帳單應收","截至月底已抵付帳單","當月帳單未付","當月租金水電實收","當月結算補繳實收","當月分攤支出","月底持有押金","當月淨收款（不含押金轉帳）","狀態");Map<String,String> names=new HashMap<>();JSONArray p=report.getJSONArray("properties");JSONObject total=report.getJSONObject("total");csvRow(out,report.getString("month"),"總計",total.getString("name"),"","",total,"");for(int i=0;i<p.length();i++){JSONObject r=p.getJSONObject(i);names.put(r.getString("id"),r.getString("name"));csvRow(out,report.getString("month"),"不動產",r.getString("name"),"","",r,"");}JSONArray tenants=report.getJSONArray("tenants");for(int i=0;i<tenants.length();i++){JSONObject r=tenants.getJSONObject(i);csvRow(out,report.getString("month"),"租約",names.get(r.getString("propertyId")),r.getString("code"),r.getString("name"),r,r.getString("status"));}return out.toString();
    }
    private static void csvRow(StringBuilder out,String month,String kind,String property,String code,String tenant,JSONObject r,String status)throws JSONException {line(out,month,kind,property,code,tenant,r.optString("billed"),r.optString("paid"),r.optString("remaining"),r.optString("cash"),r.optString("topups"),kind.equals("租約")?"":r.optString("expenses"),r.optString("held"),kind.equals("租約")?"":r.optString("net"),status);}
}
